+fn push_frustum(out: &mut Vec<MeridianAtom>, p: (f64, f64), q: (f64, f64), cutting: bool) {
+    if q.0 - p.0 > EPS {
+        out.push(MeridianAtom {
+            z0: p.0,
+            z1: q.0,
+            shape: AtomShape::Frustum { r0: p.1, r1: q.1 },
