+fn mill(kind: ToolKind, d: f64, corner_r: f64, tip_angle: f64, fl: f64) -> Tool {
+    Tool {
+        corner_r,
+        ..cutter(kind, d, fl, d * 0.5, 30.0, tip_angle)
+    }
