+/// The largest atom radius at `z` (the union's radius).
+fn union_rho(atoms: &[MeridianAtom], z: f64) -> f64 {
+    atoms
+        .iter()
+        .filter(|a| a.z0 - 1e-12 <= z && z <= a.z1 + 1e-12)
+        .fold(0.0, |m, a| m.max(a.rho(z)))
