+#[test]
+fn degenerate_meridians_are_refused_by_name() {
+    let l = SpunPoint::line;
+    let new = |p: Vec<SpunPoint>| {
+        let n = p.len().saturating_sub(1);
+        Meridian::new(p, vec![true; n])
