+    );
+    assert_eq!(
+        new(vec![l(0.0, 0.0), l(f64::NAN, 1.0)]),
+        Err(MeridianError::NonFinite(2))
+    );
+    assert_eq!(
+        new(vec![l(0.0, 0.0), arc(0.0, 1.0, f64::INFINITY), l(5.0, 1.0)]),
+        Err(MeridianError::NonFinite(2))
